{
  "purpose": "审实际保存的世界19/圣经30/计划29中值守及失箱桥接和第33–35章叙事质量。未来提案可评可执行性，未采纳本身不是错误；不要把旧正文混入。36–39仅审已提供宏观的衔接，不假设缺少的逐章细节已经落地。本次不是全书验收。",
  "previousDisposition": {
    "rawVerdicts": "guards/box/drama all revise",
    "accepted": [
      "补无替班就取消移送、不顺延制造空岗",
      "补口头暂存权限、侧门空箱底册与船方失职",
      "补火毁独立材料及证据不足保留未知",
      "补严请求改口、林拒收、严反咬的具体互动"
    ],
    "scopeLimit": "未采纳不是计划不能成立的理由；报告评的仍是未来提案，不把任何局部通过当正文或全书通过。",
    "rereviewedFinal": false
  }
}

{
  "status": "proposed_not_adopted",
  "roles": {
    "gate": "太清本批名册仍有人在古境期间的接待与护送岗位；全员退出并销班后可撤桌，不代表关闭或遗弃整个三方古境。",
    "custody": "任何时候至少一名实际在场的玄府负责墨，不用凡绳宣称永久封禁。"
  },
  "movements": [
    {
      "day": 60,
      "where": "loc_29",
      "people": [
        "char_10",
        "char_12",
        "char_13"
      ],
      "event": "顾说明原先已排的后半期轮换：褚衡、邵闻第186日从外门出发，188日暮到外营，189日交班。抽调邵减少一条外山晚巡，褚的一段例行巡检延期；尚不知道会擒获墨。顾当日寿储下界至少12。"
    },
    {
      "day": 180,
      "where": "loc_29",
      "people": [
        "char_17",
        "char_18"
      ],
      "event": "二人核对186出发的行粮、执事牌和换班期，拒绝提前同行帮主角争泉；本批太清预计211日前结束，伤病则延后销班。"
    },
    {
      "fromDay": 186,
      "toDay": 188,
      "where": "loc_04→loc_05外营",
      "people": [
        "char_17",
        "char_18"
      ],
      "event": "沿与首批同一山路行三日，188日暮到达入口外营；25章战斗已结束，不倒填他们援助顾擒墨。"
    },
    {
      "day": 189,
      "where": "loc_05外营",
      "people": [
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "乔辰初向顾接墨。189起杜/褚轮入口、乔/邵轮看押；每人12小时当值12小时休息。入口与囚棚各一人，顾疗伤不计入值班容量。"
    },
    {
      "fromDay": 203,
      "toDay": 211,
      "where": "loc_05外营",
      "people": [
        "char_10"
      ],
      "event": "顾复诊只准每日最多2小时入口轻值，具体面交前由杜或褚继续负责；短班只给该值守额外休息，不代替四人基础轮班。"
    },
    {
      "day": 212,
      "where": "loc_05外营",
      "people": [
        "char_02",
        "char_09",
        "char_10",
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "林随车已离开后，剩余采集者逐名退出，杜褚对全部太清本批名册点验，签本批销班；发现缺人则延后返程。白榆批准伤者坐车，顾不承担擒敌值守。"
    },
    {
      "fromDay": 213,
      "toDay": 216,
      "where": "loc_05外营→loc_29",
      "people": [
        "char_02",
        "char_04",
        "char_09",
        "char_10",
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "按有伤者的慢车四日返外门。乔和邵分昼夜各12小时近身看墨，另一人随队车休息；杜褚分别护前后路、轮换休息，苏护证，白榆顾随医车。无未交接离岗、无人把睡眠记作继续看押。"
    },
    {
      "fromDay": 216,
      "toDay": 436,
      "where": "loc_29值守房",
      "people": [
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "四名玄府轮一处羁押岗，每人6小时；其余时间休息或在不重叠的时段执行宗门事务。墨就医或移房由休班者提前面交增援，缩减外山例行巡检并记加班俸，不使用自创封禁。顾康复后指导林修行，不在此班表里重复计数。"
    },
    {
      "fromDay": 437,
      "toDay": 466,
      "where": "loc_29两间值守房",
      "people": [
        "char_12",
        "char_13",
        "char_17",
        "char_18"
      ],
      "event": "邵辰初当面接顾交来的伤押卫，乔仍看墨。此后墨岗乔日/杜夜，伤押卫岗邵日/褚夜，均12小时值12小时休，暂停四人其他外出差事。顾签完交接才就医。白榆在原值守房门旁诊疗，当班玄府仍近身看守，不调用休班者作日常搬运。原地无法安全诊治时封住普通通道、医修进房，原看守不离开；本阶段不安排跨房或外送。所有非紧急移房、提审与外送在无具名且足休替班者实际到岗时一律取消，不挪下一班补洞。若临时出现当班失能等必须增援事件，这张四人班表不够，该情节须先另审可覆盖的人手方案，不能照旧继续。"
    }
  ],
  "guLife": {
    "baselineDay": 60,
    "lowerBound": 12,
    "casts": [
      {
        "day": 188,
        "cost": 0.25
      },
      {
        "day": 436,
        "cost": 0.25
      }
    ],
    "balance436": 10.46986301369863,
    "note": "原章15的基线是第60日，不是第180日；不靠重新诊断制造120日寿元。"
  },
  "guardSleepHoursPerDay": {
    "189-211": {
      "char_12": 12,
      "char_13": 12,
      "char_17": 12,
      "char_18": 12
    },
    "216-436": {
      "char_12": 18,
      "char_13": 18,
      "char_17": 18,
      "char_18": 18
    },
    "437-466": {
      "char_12": 12,
      "char_13": 12,
      "char_17": 12,
      "char_18": 12
    },
    "interpretation": "18为未当羁押岗的时间，不全当睡眠；其他宗务只能在有至少连续8小时休息之外安排。途中乔邵轮押，每人实际在车休息12小时；杜褚白日护前后路、夜营原地歇，警戒由当夜押班观察车旁，不假设沿途另战。"
  }
}

{
  "status": "proposed_not_adopted",
  "contents": {
    "box6Original": 24,
    "unit": "包普通低阶草药",
    "recovered": 12,
    "burned": 6,
    "soldAndUsed": 6,
    "total": 24
  },
  "timeline": [
    {
      "day": 214,
      "event": "实际装箱清单列六号箱24包普通药材，31章港验与清单一致。"
    },
    {
      "day": 215,
      "event": "严涛想私卖抵赌债，私推六号箱到侧舱时夹伤脚；林忙救人。严叫水手常钧把该箱搬去普通备缆间避浪，常不知偷卖意图，亲自留暂存粉板记号。严之后涂掉记号，林清点本货舱只见五箱，未获全船搜查权。"
    },
    {
      "day": 216,
      "event": "靠港后第六箱仍在备缆间，不是海上被高阶术法送走；林尚未知道。"
    },
    {
      "day": 217,
      "event": "严以旧识找陆沉舟弟弟，把箱从备缆间经普通卸货侧门交程记；陆弟按程记便条领走，常帮抬至码头但不跟去仓。严实收私卖款，借脚伤不下船查验；程暂不来正式接五箱。"
    },
    {
      "fromDay": 218,
      "toDay": 223,
      "event": "程记医铺售出其中6包已用于普通伤病，留有对应散卖页；12包带原批签存后架，6包留前柜。不能把24包重新算成无数箱禁药或高品火髓。"
    },
    {
      "day": 225,
      "event": "第37章程记仓火，前柜6包焚毁。林先救陆弟，水手与贺从仓边搬出后架带原批签12包；主角手受伤不搬重物。箱外板刻号与绳孔吻合，能够认出处而不能自动证明海上经过。"
    },
    {
      "fromDay": 227,
      "toDay": 230,
      "event": "38章常当面指两次搬运的位置与侧门底册，严在其证言和陆弟领货便条前承认私挪、擦板；39章以12包实物、分架页、前柜焦吊签及医铺接用页核账。原船主收回12包；6包已用于病人不追讨患者，6包火毁依独立材料判断，证据不足须保留未知。剩余追偿未收不记收入。"
    }
  ],
  "knowledge": [
    {
      "chapter": 33,
      "linKnows": "从船册确认被救押货者姓名严涛；失箱仍未知。"
    },
    {
      "chapter": 35,
      "linKnows": "常说明215日暂存与217日抬至侧门，未知领货人身份；次日粉板已无编号，常没看见谁擦。"
    },
    {
      "chapter": 37,
      "linKnows": "火场取到外板与12包原签药，知道箱到过程记。"
    },
    {
      "chapter": 38,
      "linKnows": "严承认私挪、常复述实搬路径，陆弟便条与二人签认交叉核对。"
    },
    {
      "chapter": 39,
      "linKnows": "24包分成12回收/6烧损/6已售用；海上私挪与到港交货可以复核，不等于已经证明赵指使仓火或九鼎全网。"
    }
  ],
  "liability": "林失去既定履约奖金和复验费，不把救人的选择写成偷卖同谋；原船主承认其有权在未获准的情况下不搜备缆间，不追加全箱赔债。严、收赃方及船主各承担可证责任，追偿未收不填成收入。",
  "payoff": "第39章查清本箱去向与责任分配，本线可在后续实际章节验收后收束；第100章无需仍把箱板当无解谜题。",
  "accessAndEvidence": {
    "authority": "严作为当航押货者可进入其负责货舱，船上风暴规程允许押货者口头叫当舱水手把松箱搬入相邻备缆间避浪；搬运须在舱口粉板留编号，暂存不构成出货授权。常亲手写六号，严拄杖在暴风后擦掉编号并谎报检查过备缆间，未搬重物。",
    "search": "215日风暴未止船方先封闭通往备缆间的积水通道，依严口头回报暂记可能失落待靠港复查；林要求全船复查但没获准，也不能私闯船员工作区。216日暮外锚等待卸货位，暂存间未核。217日早晨卸货前检查前，严先以旧识领走。船主之后承认只听口头回报而漏复查的责任。",
    "gate": "217日严仍在船上，坐着把六号箱外覆杂绳，持自己的押货工牌向值门水手报作损坏空箱领走；陆弟持程记写的普通领废箱便条来接。值门水手只记严工牌、陆弟姓名和空箱一件，未拆看，常受命抬到侧门才发现重量不像空箱却因怕失工没说。侧门是可合法领旧包装的门，不是无守无人知的秘道；权限被滥用且检查失职，不是完好放行。",
    "fire": "陆弟218日亲手分原24包：前柜6、后架12、当天送医铺6；当天入仓分架页由其与陆沉舟共同点数，作为批签对应材料之一。225日搬出的12包原签完整；灭火后前柜位置留下6枚烧焦仍可辨本批小木吊签和药包残灰，由灭火工与陆弟分别指认原处，林只在安全后核对。售出6包有医铺接收页与实际用药数，由医铺伙计在39章到港签核，林不凭账本单方认定。",
    "limits": "交接便条与侧门底册支持到港交货，常只见搬至侧门；陆弟与陆对分架的证言涉及自身责任，不单独作为无误凭据。前柜6枚本批吊签、两处账与12包原物支持6包火毁这一较强判断，不证明纵火者身份；若后续现场材料不足或异议成立，火毁项降为去向待查并阻塞本线收束。"
  },
  "drama": "第34章严要求林把私推改说成林安排的避浪转移，愿分售药款并声称救人就该帮到底。林拒收未明来源的钱，只签亲见救人与未见最后去向；严转而向船主指责林脱岗，迫使其暂失查看备缆间的机会。第35章常怕停工仍说自己听谁口令、搬到哪，不指认没见过的程记收货和售药。",
  "chapterDates": {
    "33": [
      217,
      217
    ],
    "34": [
      218,
      219
    ],
    "35": [
      220,
      221
    ],
    "36": [
      222,
      224
    ],
    "37": [
      225,
      226
    ],
    "38": [
      227,
      228
    ],
    "39": [
      229,
      230
    ]
  }
}

